// Cart amount before rounding to whole yen. `discount` is the customer's discount
// rate (0.1 = 10%), applied once. Carts with 10 or more lines then get an extra
// 5% bulk discount, also applied once.
export function exactTotal(items, discount = 0) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= 10 ? 0.05 : 0;
  return subtotal * (1 - discount) * (1 - bulk);
}

// Cart total in whole yen: fractions of a yen are dropped.
export function total(items, discount = 0) {
  // Snap away binary floating-point noise first, so an amount that is really a
  // whole number of yen (e.g. 100 * (1 - 0.43) = 57.00000000000001 or
  // 56.99999999999999) is not floored to one yen less.
  return Math.floor(Number(exactTotal(items, discount).toFixed(6)));
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}
